.界 {
  position: relative;
  display: flex;
  flex-direction: column;
  // 高度由 index.ts/App 设好的 iframe 高度决定。100% 而不是 vh —— vh 在 iframe 里
  // 指的是 iframe 自己的高度, 会绕成一个圈。
  height: 100%;
  background: linear-gradient(178deg, #252b23 0%, #171d1b 100%);
  color: #ddd1b5;
  font-size: 15px;
  line-height: 1.75;
  -webkit-tap-highlight-color: transparent;
  overflow: hidden;

  &__顶 {
    flex: none;
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 14px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
    background: rgba(255, 255, 255, 0.02);
  }

  &__标 {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    line-height: 1.3;
  }

  &__名 {
    color: #e5d8b8;
    font-weight: 600;
    font-size: 0.98em;
    letter-spacing: 0.03em;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  &__日 {
    color: #96967e;
    font-size: 0.76em;
  }

  /* 台子 = 正文 + 盖在它上面的三页。底下那三页是 absolute, 靠它定位 */
  &__台 {
    position: relative;
    display: flex;
    flex-direction: column;
    flex: 1;
    min-height: 0;
  }

  /* 正文。**常驻有布局**, 不参与 v-show —— 见模板里那段注释:
     藏成 display:none 会丢滚动位置, 看诊回来就被弹回开头 */
  &__文 {
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    overscroll-behavior: contain;
    padding: 24px clamp(18px, 4.5%, 48px) 32px;
    background: #171e1d;

    p {
      margin: 0 0 1em;
      // 中英混排时首行不缩进, 靠段间距分节 —— 手机窄屏下缩进太吃宽度。
      color: #eee9df;

      &:last-child {
        margin-bottom: 0;
      }
    }
  }

  /* 折叠块 —— 预设的思维链、选项、摘要这些。默认收成一行, 点开才看。
     为什么不索性丢掉: 判据失手时"丢掉"是**不报错**的静默失败, 玩家只会觉得剧情凭空少了一截;
     折起来最坏也只是折错了哪一块, 内容一直都在。 */
  &__折 {
    margin: 0 0 1em;
    border: 1px solid rgba(255, 255, 255, 0.06);
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.025);

    &:last-child {
      margin-bottom: 0;
    }

    &[open] {
      background: rgba(255, 255, 255, 0.045);

      /* 展开时把小三角转 90 度 */
      > summary::before {
        transform: rotate(90deg);
      }
    }

    /* 行内的「原文」折叠条 —— 双语预设那条外语轨。
       比整块的折叠**更轻**: 一屏会出现二三十条, 用整块那样的边框和底色会把正文切成碎片。
       所以底色不要、只留一条左边线, 并且上边距收一点, 让它贴住上面那句译文。 */
    &.is-原文 {
      margin: -0.4em 0 1em;
      border: 0;
      border-left: 2px solid rgba(255, 255, 255, 0.1);
      border-radius: 0;
      background: none;

      &[open] {
        background: none;
      }

      > .界__折头 {
        padding: 3px 10px;
        font-size: 0.76em;
      }

      > .界__折体 {
        padding: 0 10px 6px 20px;
        font-size: 0.84em;
      }
    }
  }

  &__折头 {
    display: flex;
    align-items: center;
    gap: 9px;
    padding: 7px 11px;
    font-size: 0.82em;
    letter-spacing: 0.04em;
    cursor: pointer;
    /* 干掉浏览器默认那个三角: 它的大小和位置各家不一样, 留着跟文字对不齐 */
    list-style: none;

    &::-webkit-details-marker {
      display: none;
    }

    /* 自己画一个, 用 currentColor 所以跟着状态色走 */
    &::before {
      content: '';
      flex: none;
      width: 0;
      height: 0;
      border-left: 4px solid currentColor;
      border-top: 3.5px solid transparent;
      border-bottom: 3.5px solid transparent;
      transition: transform 0.15s ease;
    }
  }

  &__折名 {
    flex: 1;
    min-width: 0;
    overflow: hidden;
    color: #a6ab91;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  &__折数 {
    flex: none;
    color: #4d5866;
    font-variant-numeric: tabular-nums;
  }

  &__折体 {
    padding: 0 11px 10px 24px;
    color: #96967e;
    font-size: 0.88em;
    line-height: 1.65;
    /* 折叠块里是原样的文本, 换行得留住 */
    white-space: pre-wrap;
    word-break: break-word;
  }

  &__笔 {
    display: inline-block;
    color: #d7c38d;
    // 动画名用 ASCII。Vue 的 scoped 样式会重写 @keyframes 的名字, 非 ASCII 容易被漏掉,
    // 结果就是引用不到、光标不闪 —— 而且不报错。跟组件标签名那条坑是同一类。
    animation: th-blink 1s steps(2, start) infinite;
  }

  &__空 {
    color: #4d5866;
    font-size: 0.9em;
  }

  /* 盖在正文上的那三页。
     不透明底是**必要**的: 它是「换了一页」, 不是「弹了个窗」, 底下不该透出正文。
     底色跟 .界 那份一样 —— 页只盖住中间这一段, 上下分别是顶栏和标签条,
     两段渐变各自从头开始, 接缝在 #252b23 上, 看不出来。
     每块自带 .界卡 的 margin, 左右留一点免得贴边。 */
  &__页 {
    position: absolute;
    inset: 0;
    overflow-y: auto;
    overscroll-behavior: contain;
    padding: 0 12px 12px;
    background: linear-gradient(178deg, #252b23 0%, #171d1b 100%);

    /* 让每一页成为**尺寸查询容器** —— 家园页那张九宫格要按「这一页有多高」定边长,
       用的就是这里的 cq 单位 (见 九宫格.vue 的 .宫)。
       用 size 而不是 inline-size: 要量的是**高**, inline-size 量不到高。
       contain 不影响这一页自己: 它的尺寸来自 inset: 0, 本来就不看内容。 */
    container-type: size;
  }

  /* 五个等宽标签 = 五个页面。位置固定在底部, 不再被展开的面板顶上去。
     开着的那页靠 is-开 的底色认 —— 互斥的按钮更像标签页, 加箭头反而说不清它管哪一块 */
  &__签 {
    flex: none;
    display: flex;
    border-top: 1px solid rgba(255, 255, 255, 0.06);
  }

  &__态标 {
    display: flex;
    align-items: center;
    /* 居中对齐 —— 四个标签里有两个带角标, 左对齐会让「申请」「家园」的文字
       比另外两个偏一截, 一排看过去是歪的 */
    justify-content: center;
    gap: 7px;
    flex: 1;
    min-width: 0;
    min-height: 42px;
    /* 每加一个标签, 每个就窄一档, 而 320px 宽的机器上本来就已经贴着边了:
       三个 → 四个时内边距从 14px 收到 10px, 四个 → 五个时由下面那条
       @media (max-width: 420px) 再收到 5px。**再要加第六个就得先量一遍**,
       照这个收法会先把「申请」的角标挤出去。 */
    padding: 0 10px;
    border: none;
    background: rgba(255, 255, 255, 0.02);
    color: #a6ab91;
    font-family: inherit;
    font-size: 0.86em;
    letter-spacing: 0.06em;
    cursor: pointer;

    i {
      color: #5c6773;
      font-size: 0.9em;
    }

    /* 开着的那一块。`i` 那条规则留着 —— 现在没有箭头图标, 但将来加回来时
       它会自动跟着变色, 不用再改两处 */
    &.is-开 {
      background: rgba(215, 195, 141, 0.08);
      color: #e5d4a3;

      i {
        color: #e5d4a3;
      }
    }
  }

  /* 不再 `margin-left: auto` —— 那是在左对齐的标签里把角标甩到右边的写法。
     现在整行居中, 角标跟着文字走, 由 gap 隔开就对了 */
  &__角标 {
    flex: none;
    padding: 1px 8px;
    border-radius: 999px;
    background: rgba(215, 195, 141, 0.14);
    border: 1px solid rgba(215, 195, 141, 0.3);
    color: #e5d4a3;
    font-size: 0.86em;
    font-variant-numeric: tabular-nums;
  }

  &__底 {
    flex: none;
    display: flex;
    gap: 9px;
    padding: 10px 14px 14px;
    border-top: 1px solid rgba(255, 255, 255, 0.06);
    background: rgba(255, 255, 255, 0.02);
  }

  &__钮 {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    min-height: 40px;
    padding: 0 16px;
    border-radius: 9px;
    border: 1px solid rgba(255, 255, 255, 0.09);
    background: rgba(255, 255, 255, 0.045);
    color: #b8baa4;
    font-family: inherit;
    font-size: 0.9em;
    cursor: pointer;
    transition: background 0.18s ease, opacity 0.18s ease;

    &:disabled {
      opacity: 0.4;
      cursor: default;
    }

    &:not(:disabled):hover {
      background: rgba(255, 255, 255, 0.09);
    }

    &.is-主 {
      flex: 1;
      background: rgba(215, 195, 141, 0.14);
      border-color: rgba(215, 195, 141, 0.34);
      color: #e5d4a3;

      &:not(:disabled):hover {
        background: rgba(215, 195, 141, 0.24);
      }
    }

    &.is-历史 {
      flex: none;
      min-height: 32px;
      padding: 0 11px;
      font-size: 0.82em;
      color: #a6ab91;

      &.is-开 {
        background: rgba(215, 195, 141, 0.14);
        border-color: rgba(215, 195, 141, 0.3);
        color: #e5d4a3;
      }
    }
  }

  /* 窄屏(320~420px 那段)四个标签会把「申请」的角标挤出去。整条收一档 */
  @media (max-width: 420px) {
    &__态标 {
      padding: 0 5px;
      gap: 4px;
      font-size: 0.78em;
      letter-spacing: 0.02em;
    }

    &__角标 {
      padding: 1px 5px;
    }
  }
}

.史 {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: flex;
  flex-direction: column;
  background: #171d1b;

  &__顶 {
    flex: none;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 10px 14px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
    color: #e5d8b8;
    font-weight: 600;
  }

  &__体 {
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    overscroll-behavior: contain;
    padding: 14px 16px 24px;
  }

  &__条 {
    margin-bottom: 16px;

    p {
      margin: 0;
      color: #b8baa4;
      font-size: 0.94em;
      white-space: pre-wrap;
    }

    &.is-user p {
      color: #a6ab91;
      font-style: italic;
    }
  }

  &__签 {
    display: block;
    margin-bottom: 3px;
    color: #4d5866;
    font-size: 0.76em;
    letter-spacing: 0.1em;
  }
}

@keyframes th-blink {
  50% {
    opacity: 0;
  }
}
