
/* 外壳(底色/圆角/阴影)在 global.css 的 .界卡 上, 其余三个块共用。 */
.世界 {
  &__角 {
    padding-bottom: 10px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  }

  &__主线 {
    margin: 0;
    color: #c8c7af;
    font-size: 0.9em;
    line-height: 1.6;
  }

  &__事件 {
    margin: 7px 0 0;
    padding: 0;
    list-style: none;

    li {
      display: flex;
      flex-wrap: wrap;
      gap: 0 8px;
      margin-top: 4px;
      font-size: 0.8em;
      line-height: 1.5;
    }
  }

  &__事件名 {
    flex: none;
    color: #8c98a6;
  }

  &__事件态 {
    flex: none;
    color: #7fd6a0;
  }

  &__事件说 {
    flex: 1 1 100%;
    color: #5f6a77;
  }

  /* ── 报纸 ──────────────────────────────────────────────────────
     这一块**故意不跟着界面的无衬线字体走**: 报纸要看起来像印出来的。
     衬线 + 偏暖的纸色, 跟上下两块灰蓝色的界面拉开距离 —— 玩家一眼就知道
     自己是在「读报」, 而不是在看又一个数据面板。 */
  &__报 {
    margin-top: 12px;
    padding: 12px 13px 4px;
    border-radius: 7px;
    background: rgba(226, 214, 190, 0.045);
    border: 1px solid rgba(226, 214, 190, 0.1);
    font-family: Georgia, 'Songti SC', 'SimSun', 'Noto Serif CJK SC', serif;
  }

  &__报头 {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 10px;
    padding-bottom: 7px;
    /* 报头下面那道双线: 一粗一细, 是报纸的样子 */
    border-bottom: 3px double rgba(226, 214, 190, 0.28);
  }

  &__报名 {
    color: #ece3d2;
    font-size: 1.16em;
    font-weight: 700;
    /* 报名字距拉开一点, 像铅字排出来的 */
    letter-spacing: 0.16em;
  }

  &__报日 {
    flex: none;
    color: #8a8172;
    font-size: 0.76em;
  }

  &__版 {
    margin-top: 12px;
  }

  &__版名 {
    margin: 0 0 7px;
    padding-bottom: 4px;
    border-bottom: 1px solid rgba(226, 214, 190, 0.16);
    color: #b0a693;
    font-size: 0.78em;
    font-weight: 600;
    letter-spacing: 0.22em;
  }

  /* 报纸里的一则。**故意不叫 `条`** —— 上面世界一角那一行已经叫 `条` 了,
     同名的话那一行的 flex 排版会漏进报纸里 (flex-wrap / gap 都还在),
     叠一层父选择器去盖只是在跟自己的样式打架。两个东西本来就不同名才对。 */
  &__闻 {
    margin-bottom: 11px;

    &:last-child {
      margin-bottom: 0;
    }
  }

  &__题 {
    margin: 0 0 3px;
    color: #e2d9c8;
    font-size: 0.92em;
    font-weight: 600;
    line-height: 1.45;
  }

  &__文 {
    margin: 0;
    color: #a89f8e;
    font-size: 0.84em;
    line-height: 1.7;
    /* 报纸正文两端对齐, 行尾才不会有豁口 */
    text-align: justify;
  }

  &__署 {
    margin: 3px 0 0;
    color: #7a7264;
    font-size: 0.76em;
    text-align: right;
  }

  /* 玩家自己买的那一则。整块报纸都是灰黄的, 只有它是亮的 ——
     花了钱的东西得一眼看见, 否则玩家会以为钱白花了。 */
  &__闻.is-投稿 {
    margin: 0 -6px 11px;
    padding: 7px 6px 7px 9px;
    border-left: 2px solid rgba(215, 195, 141, 0.45);
    background: rgba(215, 195, 141, 0.05);

    .世界__题 {
      color: #cfeeff;
    }

    .世界__文 {
      color: #9fb3bf;
    }
  }

  &__印 {
    margin-left: 6px;
    padding: 1px 5px;
    border-radius: 3px;
    background: rgba(215, 195, 141, 0.16);
    color: #e5d4a3;
    font-family: system-ui, sans-serif;
    font-size: 0.68em;
    font-weight: 400;
    letter-spacing: 0.06em;
    vertical-align: 2px;
    white-space: nowrap;
  }

  /* 往期。压在报纸最底下, 用同色系的线框 —— 它还是报纸的一部分, 不该长得像界面控件。 */
  &__往 {
    margin: 4px 0 10px;
    border-top: 1px solid rgba(226, 214, 190, 0.16);
  }

  &__往头 {
    padding: 7px 0 2px;
    color: #8a8172;
    font-size: 0.76em;
    letter-spacing: 0.1em;
    cursor: pointer;
    list-style: none;

    &::-webkit-details-marker {
      display: none;
    }
  }

  &__往体 {
    padding-top: 4px;
  }

  &__往条 {
    display: flex;
    gap: 8px;
    padding: 3px 0;
    font-size: 0.78em;
  }

  &__往日 {
    flex: none;
    color: #6b6459;
    font-variant-numeric: tabular-nums;
  }

  &__往名 {
    flex: 1;
    min-width: 0;
    color: #8a8172;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /* ── 投稿 ────────────────────────────────────────────────────── */
  &__投稿 {
    margin-top: 14px;
  }

  &__投过 {
    margin: 0;
    padding: 9px 11px;
    border-radius: 7px;
    background: rgba(255, 255, 255, 0.03);
    color: #96967e;
    font-size: 0.82em;
  }

  &__折 {
    border: 1px solid rgba(255, 255, 255, 0.07);
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.025);

    &[open] {
      background: rgba(255, 255, 255, 0.04);
    }
  }

  &__折头 {
    display: flex;
    align-items: center;
    gap: 9px;
    padding: 10px 12px;
    color: #b8baa4;
    font-size: 0.86em;
    cursor: pointer;
    list-style: none;

    &::-webkit-details-marker {
      display: none;
    }
  }

  &__折名 {
    flex: 1;
    min-width: 0;
  }

  &__折价 {
    flex: none;
    color: #5f6a77;
    font-size: 0.88em;
  }

  &__折体 {
    padding: 0 12px 12px;
  }

  &__版们 {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
  }

  &__版钮 {
    display: flex;
    align-items: baseline;
    gap: 5px;
    padding: 6px 10px;
    border-radius: 6px;
    border: 1px solid rgba(255, 255, 255, 0.09);
    background: rgba(255, 255, 255, 0.03);
    color: #a6ab91;
    font-family: inherit;
    font-size: 0.82em;
    cursor: pointer;

    &.is-选 {
      border-color: rgba(215, 195, 141, 0.36);
      background: rgba(215, 195, 141, 0.12);
      color: #e5d4a3;
    }
  }

  &__版价 {
    color: #5f6a77;
    font-size: 0.86em;
    font-variant-numeric: tabular-nums;

    .世界__版钮.is-选 & {
      color: #7fb8cc;
    }
  }

  &__提 {
    margin: 9px 0 8px;
    color: #96967e;
    font-size: 0.78em;

    b {
      color: #a6ab91;
      font-weight: 600;
    }
  }

  &__入 {
    display: block;
    width: 100%;
    margin-bottom: 7px;
    padding: 8px 10px;
    border-radius: 6px;
    border: 1px solid rgba(255, 255, 255, 0.09);
    background: rgba(0, 0, 0, 0.22);
    color: #ddd1b5;
    font-family: inherit;
    font-size: 0.84em;
    line-height: 1.6;
    box-sizing: border-box;

    &::placeholder {
      color: #4d5866;
    }

    &:focus {
      outline: none;
      border-color: rgba(215, 195, 141, 0.35);
    }
  }

  &__区 {
    resize: vertical;
    min-height: 62px;
  }

  &__交行 {
    display: flex;
    align-items: center;
    gap: 9px;
    margin-top: 2px;
  }

  &__交 {
    flex: none;
    padding: 9px 14px;
    border-radius: 7px;
    border: 1px solid rgba(215, 195, 141, 0.34);
    background: rgba(215, 195, 141, 0.14);
    color: #e5d4a3;
    font-family: inherit;
    font-size: 0.86em;
    cursor: pointer;

    &:disabled {
      opacity: 0.4;
      cursor: default;
      border-color: rgba(255, 255, 255, 0.09);
      background: rgba(255, 255, 255, 0.04);
      color: #96967e;
    }
  }

  &__拦 {
    color: #b98a8a;
    font-size: 0.76em;
    line-height: 1.4;
  }
}

/* 占卜的样式 (占卜入口 + 翻牌那两层) 随功能一起搬去 诊所/App.vue 了。
   这一版的世界页只有三块: 主线条、报纸、投稿, 样式也在上面那三段里。 */
.世界.界卡{font-size:17px;color:#e8e4d7;line-height:1.9;padding:20px 24px}.世界 .世界__事件 li{display:block;font-size:16px;line-height:1.9}.世界 .世界__事件说,.世界 .世界__事件态{display:inline;flex:none;margin:0;color:#c2c9b6}.世界 .世界__主线,.世界 .世界__文{font-size:17px;line-height:2;color:#e3e4d8}.世界 .世界__题{font-size:20px;line-height:1.7}.世界 .世界__版名{font-size:17px}.世界 .世界__报日,.世界 .世界__署,.世界 .世界__提,.世界 .世界__往头,.世界 .世界__折头,.世界 .世界__入{font-size:15px}.世界 .世界__报名{font-size:28px}.世界 .世界__报{padding:20px}@media(max-width:600px){.世界.界卡{padding:16px}.世界 .世界__报{padding:14px}.世界 .世界__题{font-size:19px}.世界 .世界__报名{font-size:25px}}
.city-life{border-bottom:1px solid #b4b18750;padding:0 0 20px;margin-bottom:22px}.city-life header{display:flex;align-items:baseline;justify-content:space-between;gap:12px;flex-wrap:wrap}.city-life h3{font-size:23px;font-weight:400;margin:0}.city-life header span,.city-life small,.life-hint{font-size:14px;color:#bfc6b3}.city-life p{font-size:17px;line-height:1.9}.city-life .festival{color:#ecd18a}.city-life summary{cursor:pointer;font-size:16px}.city-life article{padding:14px 0;border-bottom:1px solid #929a782b}.city-life h4{margin:0 0 8px;font-size:18px}
