
.家园 {
  &__头 {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 10px;
    margin-bottom: 9px;
  }

  &__名 {
    color: #e5d8b8;
    font-weight: 600;
    letter-spacing: 0.03em;
  }

  &__数 {
    color: #7d8896;
    font-size: 0.82em;
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }

  &__注 {
    margin: 9px 0 0;
    color: #55606d;
    font-size: 0.78em;
  }

  /* 弹层的罩子。fixed + inset 0 盖住整个 iframe —— 它 Teleport 到 body,
     不属于折叠区。点空白处关掉 */
  &__罩 {
    position: fixed;
    inset: 0;
    z-index: 9998;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 16px;
    background: rgba(6, 9, 13, 0.72);
  }
}

.弹 {
  width: 100%;
  max-width: 340px;
  max-height: 80vh;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 13px 14px;
  border-radius: 13px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: linear-gradient(168deg, #161d27 0%, #1c241f 100%);
  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.5);
  color: #ddd1b5;
  font-size: 13px;

  &__头 {
    display: flex;
    align-items: center;
    gap: 9px;
    padding-bottom: 9px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.07);
  }

  &__题 {
    flex: 1;
    color: #e5d8b8;
    font-weight: 600;
  }

  &__钱 {
    color: #ffd76e;
    font-size: 0.86em;
    font-variant-numeric: tabular-nums;
  }

  &__关 {
    flex: none;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    border: none;
    border-radius: 7px;
    background: rgba(255, 255, 255, 0.06);
    color: #a6ab91;
    font-family: inherit;
    cursor: pointer;
  }

  &__在 {
    margin: 10px 0 0;
    color: #9aa5b1;
    font-size: 0.9em;

    strong {
      color: #e5d4a3;
    }
  }

  &__段 {
    margin-top: 12px;
  }

  &__标 {
    margin: 0 0 6px;
    color: #96967e;
    font-size: 0.8em;
    font-weight: 500;
    letter-spacing: 0.08em;
  }

  /* 一件货一行。左边名字, 右边价钱/氛围 */
  &__项 {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 10px;
    width: 100%;
    min-height: 38px;
    padding: 0 11px;
    margin-bottom: 5px;
    border-radius: 8px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    background: rgba(255, 255, 255, 0.04);
    color: #c8c7af;
    font-family: inherit;
    font-size: 0.94em;
    text-align: left;
    cursor: pointer;
    transition: background 0.18s ease;

    &:disabled {
      opacity: 0.4;
      cursor: not-allowed;
    }

    &:not(:disabled):hover {
      background: rgba(215, 195, 141, 0.13);
    }
  }

  &__价 {
    flex: none;
    color: #7d8896;
    font-size: 0.84em;
    font-variant-numeric: tabular-nums;
  }

  &__满 {
    margin: 12px 0 0;
    color: #55606d;
    font-size: 0.86em;
  }

  &__脚 {
    margin-top: 13px;
    padding-top: 11px;
    border-top: 1px solid rgba(255, 255, 255, 0.07);
  }

  /* 收起来是退回仓库, 不是卖掉 —— 文案要写明, 否则玩家不敢点 */
  &__收 {
    width: 100%;
    min-height: 38px;
    border-radius: 8px;
    border: 1px solid rgba(255, 215, 110, 0.28);
    background: rgba(255, 215, 110, 0.1);
    color: #ffd76e;
    font-family: inherit;
    font-size: 0.94em;
    cursor: pointer;

    &:hover {
      background: rgba(255, 215, 110, 0.18);
    }
  }

  &__提示 {
    display: block;
    color: #55606d;
    font-size: 0.84em;
  }
}
