
.疏导 {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  min-height: 0;
  background: linear-gradient(170deg, #12171f 0%, #0a0d13 100%);
  color: #ddd1b5;
  font-size: 14px;
  overflow: hidden;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;

  &__头 {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 10px 14px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
    flex: none;
    font-size: 0.86em;
    letter-spacing: 0.02em;
  }

  &__名 {
    color: #e5d8b8;
    font-weight: 600;
  }

  &__污 {
    color: #7d8896;
  }

  /* 「第 3 / 5 趟」—— 玩家在这里才知道这个人还得来几趟 (spec §5.2) */
  &__趟 {
    font-size: 12px;
    opacity: 0.7;
  }

  &__空 {
    flex: 1;
  }

  &__数 {
    color: #7d8896;
    font-variant-numeric: tabular-nums;

    &.is-有 {
      color: #ff9a9a;
    }

    &.is-耗 {
      color: #d7c38d;
      min-width: 5.4em;
      text-align: right;
    }
  }

  &__场 {
    position: relative;
    flex: 1;
    min-height: 0;
    touch-action: none;
    overflow: hidden;

    &.is-震 {
      animation: 震 0.3s cubic-bezier(0.36, 0.07, 0.19, 0.97);
    }
  }

  &__svg {
    display: block;
    width: 100%;
    height: 100%;
  }

  &__线 {
    stroke: #38424f;
    stroke-width: 3;
    stroke-linecap: round;
    transition:
      stroke 0.22s ease,
      stroke-width 0.22s ease,
      opacity 0.32s ease,
      transform 0.32s ease;

    &.is-亮 {
      stroke: #d7c38d;
      stroke-width: 5;
      filter: drop-shadow(0 0 6px rgba(215, 195, 141, 0.85));
    }

    &.is-错 {
      stroke: #ff7a7a;
      stroke-width: 5;
      filter: drop-shadow(0 0 6px rgba(255, 122, 122, 0.7));
    }

    &.is-清 {
      opacity: 0;
      stroke-width: 1;
    }
  }

  &__飘字 {
    position: absolute;
    transform: translate(-50%, -50%);
    padding: 3px 10px;
    border-radius: 999px;
    background: rgba(30, 18, 18, 0.9);
    border: 1px solid rgba(255, 122, 122, 0.35);
    color: #ffb4b4;
    font-size: 0.8em;
    white-space: nowrap;
    pointer-events: none;
    animation: 飘 1.5s ease-out forwards;
  }

  &__引导 {
    position: absolute;
    left: 50%;
    bottom: 18px;
    transform: translateX(-50%);
    margin: 0;
    color: #55606d;
    font-size: 0.82em;
    pointer-events: none;
  }

  &__结算 {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 14px;
    padding: 20px;
    background: rgba(8, 11, 16, 0.9);
    backdrop-filter: blur(3px);
    animation: 淡入 0.4s ease-out;
  }

  &__评级 {
    font-size: 3.4em;
    font-weight: 700;
    line-height: 1;
    letter-spacing: 0.04em;
    text-shadow: 0 0 24px currentColor;

    &.is-S {
      color: #ffd76e;
    }
    &.is-A {
      color: #d7c38d;
    }
    &.is-B {
      color: #9fb3c8;
    }
    &.is-C {
      color: #ff9a9a;
    }
  }

  &__账 {
    display: flex;
    gap: 22px;
    margin: 0;

    div {
      text-align: center;
    }

    dt {
      color: #7d8896;
      font-size: 0.76em;
      margin-bottom: 3px;
    }

    dd {
      margin: 0;
      font-size: 1.2em;
      font-variant-numeric: tabular-nums;

      &.is-有 {
        color: #ff9a9a;
      }
    }
  }

  &__日志 {
    margin: 0;
    padding: 0;
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 3px;
    max-width: 100%;
    color: #8b96a3;
    font-size: 0.8em;
    text-align: center;

    li {
      overflow-wrap: anywhere;
    }
  }

  &__脚 {
    flex: none;
    padding: 10px 14px calc(10px + env(safe-area-inset-bottom));
    border-top: 1px solid rgba(255, 255, 255, 0.06);
  }

  &__钮 {
    display: block;
    width: 100%;
    min-height: 46px;
    border-radius: 10px;
    border: 1px solid transparent;
    font-size: 0.98em;
    font-family: inherit;
    letter-spacing: 0.06em;
    cursor: pointer;
    transition:
      background 0.2s ease,
      border-color 0.2s ease;

    &.is-退 {
      background: rgba(50, 58, 68, 0.5);
      border-color: rgba(255, 255, 255, 0.07);
      color: #8b96a3;

      &:hover {
        background: rgba(60, 70, 82, 0.65);
      }
    }

    &.is-完 {
      background: rgba(215, 195, 141, 0.14);
      border-color: rgba(215, 195, 141, 0.4);
      color: #e5d4a3;

      &:hover {
        background: rgba(215, 195, 141, 0.22);
      }
    }
  }
}

@keyframes 震 {
  10%,
  90% {
    transform: translateX(-2px);
  }
  20%,
  80% {
    transform: translateX(3px);
  }
  30%,
  50%,
  70% {
    transform: translateX(-5px);
  }
  40%,
  60% {
    transform: translateX(5px);
  }
}

@keyframes 飘 {
  0% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.9);
  }
  18% {
    opacity: 1;
    transform: translate(-50%, -60%) scale(1);
  }
  100% {
    opacity: 0;
    transform: translate(-50%, -140%) scale(1);
  }
}

@keyframes 淡入 {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .疏导__场.is-震 {
    animation: none;
  }

  .疏导__线 {
    transition: opacity 0.2s ease;
  }
}
