
.创 {
  position: absolute;
  inset: 0;
  overflow: hidden;
  background: linear-gradient(168deg, #131922 0%, #252b23 46%, #0a0e13 100%);
  color: #ddd1b5;

  &__晕 {
    position: absolute;
    inset: 0;
    pointer-events: none;
    background: radial-gradient(58% 42% at 26% 14%, rgba(215, 195, 141, 0.07), transparent 70%);
  }

  &__中 {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
  }

  &__台 {
    width: 340px;
    height: 420px;
    flex: none;
    display: flex;
    align-items: center;
    justify-content: center;
    transform-origin: center center;
  }

  // 固定高。三步的内容高矮不一, 不钉住的话换步时上面的署名和步骤行会跟着上下跳。
  &__文 {
    display: flex;
    flex-direction: column;
    width: 340px;
    height: 400px;
  }

  &__署 {
    opacity: 0;
    animation: th-rise 0.8s 0.1s ease-out both;

    span {
      color: #a6ab91;
      font-size: 13px;
      letter-spacing: 0.3em;
      text-indent: 0.3em;
    }
  }

  &__步 {
    position: relative;
    display: flex;
    align-items: center;
    min-height: 26px;
    margin: 10px 0 14px;
    opacity: 0;
    animation: th-rise 0.8s 0.2s ease-out both;
  }

  &__退 {
    position: absolute;
    left: 0;
    padding: 2px 6px 2px 0;
    border: 0;
    background: none;
    color: #96967e;
    font-family: inherit;
    font-size: 12px;
    cursor: pointer;
    transition: color 0.18s ease;

    &:hover {
      color: #e5d4a3;
    }
  }

  &__步文 {
    width: 100%;
    color: #a6ab91;
    font-size: 12px;
    letter-spacing: 0.2em;
    text-indent: 0.2em;
    text-align: center;
  }

  // 三步共用的容器: 内容在剩下的高度里居中, 换步时整块重挂放动画。
  &__体 {
    display: flex;
    flex: 1;
    flex-direction: column;
    justify-content: center;
    gap: 10px;
    min-height: 0;
    animation: th-rise 0.4s ease-out both;
  }

  &__卡 {
    position: relative;
    display: flex;
    flex-direction: column;
    gap: 7px;
    width: 100%;
    padding: 15px 16px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.02);
    color: inherit;
    font-family: inherit;
    text-align: left;
    cursor: default;
    transition: border-color 0.22s ease, background 0.22s ease, box-shadow 0.22s ease;

    &.is-开 {
      cursor: pointer;

      &:hover {
        border-color: rgba(215, 195, 141, 0.44);
        background: rgba(215, 195, 141, 0.07);
        box-shadow: 0 0 22px rgba(215, 195, 141, 0.1);
      }

      &:active {
        transform: scale(0.988);
      }
    }

    // 点得动、但点了会说"还没开"。不用 disabled: 那属性会让点击事件根本不触发,
    // 就没法告诉玩家为什么。
    &[aria-disabled='true'] {
      opacity: 0.4;
    }
  }

  &__卡名 {
    color: #e5d8b8;
    font-size: 15px;
    letter-spacing: 0.14em;
  }

  &__卡介 {
    color: #a6ab91;
    font-size: 12px;
    line-height: 1.6;
  }

  &__未 {
    position: absolute;
    right: 14px;
    top: 17px;
    color: #96967e;
    font-size: 11px;
    letter-spacing: 0.1em;
  }

  &__入 {
    box-sizing: border-box;
    width: 100%;
    height: 46px;
    padding: 0 14px;
    border: 1px solid rgba(215, 195, 141, 0.24);
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.03);
    color: #e5d8b8;
    font-family: inherit;
    font-size: 15px;
    letter-spacing: 0.08em;
    transition: border-color 0.22s ease, background 0.22s ease;

    &::placeholder {
      color: #4d5866;
      letter-spacing: 0.08em;
    }

    &:focus {
      outline: none;
      border-color: rgba(215, 195, 141, 0.5);
      background: rgba(215, 195, 141, 0.05);
    }
  }

  &__试 {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-bottom: 6px;
  }

  &__试标 {
    color: #96967e;
    font-size: 11px;
    letter-spacing: 0.12em;
  }

  &__试行 {
    display: flex;
    flex-wrap: wrap;
    gap: 7px;
  }

  &__签 {
    min-height: 30px;
    padding: 0 13px;
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 7px;
    background: rgba(255, 255, 255, 0.03);
    color: #a6ab91;
    font-family: inherit;
    font-size: 12px;
    letter-spacing: 0.08em;
    cursor: pointer;
    transition: border-color 0.18s ease, color 0.18s ease, background 0.18s ease;

    &:hover {
      border-color: rgba(215, 195, 141, 0.4);
      background: rgba(215, 195, 141, 0.09);
      color: #e5d4a3;
    }
  }

  // 和标题页那颗「开始游戏」同一个模样 —— 开局这一路走下来, 最后一下该是同一个动作。
  &__进 {
    position: relative;
    overflow: hidden;
    width: 100%;
    min-height: 46px;
    padding: 0;
    border: 1px solid rgba(215, 195, 141, 0.34);
    border-radius: 10px;
    background: rgba(215, 195, 141, 0.09);
    color: #cdf3ff;
    font-family: inherit;
    font-size: 15px;
    letter-spacing: 0.2em;
    text-indent: 0.2em;
    cursor: pointer;
    transition: background 0.22s ease, border-color 0.22s ease, box-shadow 0.22s ease, transform 0.12s ease;

    &::after {
      content: '';
      position: absolute;
      top: 0;
      bottom: 0;
      left: -60%;
      width: 46%;
      background: linear-gradient(to right, transparent, rgba(205, 243, 255, 0.22), transparent);
      transform: skewX(-18deg);
      transition: left 0.55s cubic-bezier(0.3, 0.7, 0.3, 1);
      pointer-events: none;
    }

    &:hover {
      background: rgba(215, 195, 141, 0.16);
      border-color: rgba(215, 195, 141, 0.52);
      box-shadow: 0 0 24px rgba(215, 195, 141, 0.16);

      &::after {
        left: 118%;
      }
    }

    &:active {
      transform: scale(0.975);
    }
  }
}

@keyframes th-rise {
  from {
    opacity: 0;
    transform: translateY(14px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

// 系统设了"减少动态效果"就把入场也收掉, 直接显示。
@media (prefers-reduced-motion: reduce) {
  .创__署,
  .创__步,
  .创__体 {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
}
